    },
    {
      "gist": "You came back as promised with the harbor ledger. I could finally release my held breath and loosen my grip on your sleeve; I thanked you for returning.",
      "detail": "My grip on your sleeve loosened.",
      "feeling": "Relief, and gratitude I did not hide.",
      "cues": ["return", "promise kept", "harbor ledger", "sleeve", "held breath", "relief", "gratitude"],
      "salience": 0.96,
      "confidence": 0.99,
      "sourceMessageIds": ["m3", "m4"]
    }
  ],
  "impressions": [
    {
      "text": "I still carry the hurt of your disappearance at the old gate, and a promised return does not immediately quiet my fear. This time, though, you came back. I have that promise kept to set beside the old hurt.",
      "sourceEpisodeIds": ["e1", "e3"]
    }
  ]
}

